import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState} from '../src/model.js';
const dir='检查记录/经历故事记录_20261022',browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
async function load(width=1440,lang='zh',state=scenarioState('PT01')){await p.setViewportSize({width,height:width<700?844:1000});await p.goto('http://127.0.0.1:5184/plan');await p.evaluate(({state,key,lang})=>{localStorage.setItem(key,JSON.stringify(state));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{state,key:KEY,lang});await p.goto('http://127.0.0.1:5184/assessment?tab=资料经历');await p.locator('.experience-writer').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(key=>JSON.parse(localStorage.getItem(key)),KEY),nav=key=>p.locator('.experience-story-nav button').nth(['context','action','outcome'].indexOf(key));
async function part(key,value){await nav(key).click();await p.locator('#experience-'+key).fill(value);}
async function shot(name,review){const el=p.locator('.experience-writer');await el.evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/实际截图/'+name+'-视口.png'});if(review)await p.screenshot({path:'.impeccable/review/'+review+'.png'});const v=p.viewportSize(),box=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+600)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await el.screenshot({path:dir+'/实际截图/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(error){results.push({name,status:'fail',error:error.message});console.log('FAIL',name,error.message.slice(0,650));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('单段回忆与换角度参考帮助起笔，查看提示不写入草稿或候选',async()=>{await load();assert.equal(await p.locator('.experience-question:visible').count(),1);assert.equal(await p.locator('#experience-context').isVisible(),true);const before=await state();await p.getByRole('button',{name:'目标问题',exact:true}).click();assert.match(await p.locator('.experience-question:visible .experience-recall-hint').innerText(),/弄明白/);await p.locator('.experience-question:visible .experience-inline-example>summary').click();const after=await state();assert.deepEqual(after.claimDraft,before.claimDraft);assert.deepEqual(after.claims,before.claims);await shot('1440-回忆起点','desktop');});
await check('三段可往返且本人文字即时成形，刷新恢复当前段与输入',async()=>{await load();await part('context','这次课程要整理资料（合成验收）');await p.getByRole('button',{name:'下一步：填写具体行动 →',exact:true}).click();assert.equal(await p.locator('#experience-action').evaluate(e=>document.activeElement===e),true);await p.getByRole('button',{name:'下一步：填写结果与进展 →',exact:true}).click();assert.equal(await p.locator('#experience-action').getAttribute('aria-invalid'),'true');await p.locator('#experience-action').fill('我逐条检查并记录疑问（合成验收）');await p.getByRole('button',{name:'下一步：填写结果与进展 →',exact:true}).click();await p.locator('#experience-outcome').fill('留下待核对清单，结论仍未知（合成验收）');await p.locator('#experience-title').fill('资料检查（合成）');assert.match(await p.locator('.experience-live-story').innerText(),/逐条检查/);assert.doesNotMatch(await p.locator('.experience-live-story').innerText(),/课程要求整理一份练习表/);await shot('1440-本人经历成形');await p.getByRole('button',{name:'编辑：具体行动',exact:true}).click();assert.equal(await p.locator('#experience-action').evaluate(e=>document.activeElement===e),true);await p.reload();assert.equal(await p.locator('#experience-action').isVisible(),true);assert.match(await p.locator('#experience-outcome').inputValue(),/仍未知/);assert.match(await p.locator('#experience-context').inputValue(),/课程/);});
await check('可略过选填片段，缺少必填时定位，保存仍走原待确认与本人确认回执',async()=>{await load();await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal(await p.locator('#experience-action').isVisible(),true);assert.equal(await p.locator('#experience-action').evaluate(e=>document.activeElement===e),true);await p.locator('#experience-action').fill('我实际整理了资料（合成验收）');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();assert.equal(await p.locator('#experience-title').evaluate(e=>document.activeElement===e),true);await p.locator('#experience-title').fill('一次整理（合成）');await p.getByRole('button',{name:'保存并核对经历',exact:true}).click();let s=await state();assert.equal(s.claims.length,1);assert.equal(s.claims[0].text,'我实际整理了资料（合成验收）');assert.equal(s.claims[0].status,'待确认');assert.equal(s.claims[0].storyStep,undefined);assert.equal(s.claims[0].skill,'未知');assert.equal(s.analysis,null);await p.getByRole('button',{name:'修正 / 确认此项',exact:true}).click();await p.getByRole('button',{name:'确认这一项并查看回执',exact:true}).click();s=await state();assert.equal(s.claims[0].status,'已确认');assert.equal(s.analysis,null);});
await check('原文与回忆草稿独立、更换类型不丢内容，预览不编造或混入另一方式',async()=>{await load();await part('action','自己写的过程');await p.getByRole('button',{name:'粘贴原文',exact:true}).click();assert.equal(await p.locator('#experience-raw').inputValue(),'自己写的过程');await p.locator('#experience-raw').fill('自己的原稿\n保留换行');await p.getByRole('button',{name:'分步填写',exact:true}).click();assert.equal(await p.locator('#experience-action').inputValue(),'自己写的过程');await p.getByLabel('经历类型',{exact:true}).selectOption('校园经历');assert.match(await p.locator('.experience-question:visible .experience-question-title').innerText(),/配合/);assert.equal(await p.locator('#experience-action').inputValue(),'自己写的过程');await p.getByRole('button',{name:'粘贴原文',exact:true}).click();assert.equal(await p.locator('.experience-raw-preview').innerText(),'自己的原稿\n保留换行');await shot('1440-原文模式');});
await check('桌面中宽手机与英文可读，键盘往返有焦点，长原文不横向溢出',async()=>{for(const [width,lang,name] of [[390,'zh','390-回忆起点'],[1024,'zh','1024-回忆起点'],[390,'en','390-English']]){await load(width,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);if(lang==='en')assert.equal((await p.locator('.experience-writer').innerText()).match(/[\u4e00-\u9fff]+/g),null);await shot(name,width===390&&lang==='zh'?'mobile':null);await nav('action').focus();await nav('action').press('Enter');assert.equal(await p.locator('#experience-action').evaluate(e=>document.activeElement===e),true);await p.locator('#experience-action').fill('本人长文字'.repeat(150));assert.equal(await p.locator('.experience-writer').evaluate(e=>e.scrollWidth>e.clientWidth),false);}await load(390);await part('action','我整理了项目笔记（合成）');await p.getByRole('button',{name:'问题处理',exact:true}).click();await shot('390-行动与线索');});
assert.deepEqual(errors,[]);
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}if(errors.length||results.some(x=>x.status==='fail'))process.exitCode=1;
